import{_ as t,o as d,c as a,ag as n}from"./chunks/framework.DaCm-iTo.js";const g=JSON.parse('{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/strengthen/commands.md","filePath":"en/modules/strengthen/commands.md","lastUpdated":null}'),r={name:"en/modules/strengthen/commands.md"};function o(s,e,i,c,m,h){return d(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to &quot;Commands and Permissions&quot;">​</a></h1><p>The main command of EmakiStrengthen is <code>/emakistrengthen</code>, with <code>/estrengthen</code> as an alias. Commands open the strengthen GUI, inspect items, refresh presentation, set stars, clear state, give catalysts, reload configuration, and print debug information.</p><h2 id="command-list" tabindex="-1">Command list <a class="header-anchor" href="#command-list" aria-label="Permalink to &quot;Command list&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Permission</th></tr></thead><tbody><tr><td><code>/estrengthen help</code></td><td>Show help.</td><td>Basic command access.</td></tr><tr><td><code>/estrengthen open</code></td><td>Open the strengthen GUI.</td><td><code>emakistrengthen.use</code></td></tr><tr><td><code>/estrengthen reload</code></td><td>Reload configuration, GUI files, language files, and recipes.</td><td><code>emakistrengthen.reload</code> or <code>emakistrengthen.admin</code></td></tr><tr><td><code>/estrengthen inspect [player]</code></td><td>Inspect the main-hand item of yourself or the target player.</td><td><code>emakistrengthen.use</code> or <code>emakistrengthen.admin</code></td></tr><tr><td><code>/estrengthen refresh [player]</code></td><td>Refresh item presentation for yourself or the target player.</td><td><code>emakistrengthen.admin</code></td></tr><tr><td><code>/estrengthen setstar &lt;star&gt; [recipe]</code></td><td>Set the executor&#39;s main-hand item star level. There is no player argument.</td><td><code>emakistrengthen.admin</code></td></tr><tr><td><code>/estrengthen clearstate</code></td><td>Clear the strengthen layer on the executor&#39;s main-hand item. Player only.</td><td><code>emakistrengthen.admin</code></td></tr><tr><td><code>/estrengthen clearcrack</code></td><td>Clear the crack value on the executor&#39;s main-hand item. Player only.</td><td><code>emakistrengthen.admin</code></td></tr><tr><td><code>/estrengthen givecatalyst &lt;material&gt; [amount] [player]</code></td><td>Give strengthen catalyst material.</td><td><code>emakistrengthen.admin</code></td></tr><tr><td>`/estrengthen debug &lt;status</td><td>player</td><td>module</td></tr></tbody></table><h2 id="permission-nodes" tabindex="-1">Permission nodes <a class="header-anchor" href="#permission-nodes" aria-label="Permalink to &quot;Permission nodes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakistrengthen.use</code></td><td>true</td><td>Basic strengthen features.</td></tr><tr><td><code>emakistrengthen.reload</code></td><td>op</td><td>Reload configuration.</td></tr><tr><td><code>emakistrengthen.debug</code></td><td>op</td><td>Debug command.</td></tr><tr><td><code>emakistrengthen.admin</code></td><td>op</td><td>Administrative features.</td></tr></tbody></table><h2 id="admin-notes" tabindex="-1">Admin notes <a class="header-anchor" href="#admin-notes" aria-label="Permalink to &quot;Admin notes&quot;">​</a></h2><ul><li><code>setstar</code>, <code>clearstate</code>, and <code>clearcrack</code> operate on the command executor&#39;s main-hand item. Check the held item before running them.</li><li><code>refresh</code> is useful when item presentation did not update after a configuration change.</li><li>After editing recipes, run reload first, then test success, failure, protection materials, and attribute output with a test item.</li></ul>',8)])])}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
